.ds-status-tabs{background:#fff;}.ds-status-tabs {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: none;
  justify-content: space-between;
  gap: 0 4px;
  margin: 0 16px;
  flex-shrink: 0;
}
.ds-status-tabs button {
  --filter-ink: var(--brand-blue,#0032ff);
  --filter-fill: var(--brand-tint,#edf2ff);
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  min-height: var(--ui-touch-min,44px);
  min-width: var(--ui-touch-min,44px);
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--ui-body,#53637b);
  flex: none;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
  white-space: nowrap;
}
.ds-status-tabs [data-status="refunding"] {
  --filter-ink: var(--ui-warning-ink,#d97706);
  --filter-fill: var(--ui-warning-fill,#fffbeb);
}
.ds-status-tabs [data-status="refunded"] {
  --filter-ink: var(--ui-body,#53637b);
  --filter-fill: var(--ui-canvas,#f3f5fc);
}
.ds-status-tabs [data-status="failed"] {
  --filter-ink: var(--ui-danger-ink,#dc2626);
  --filter-fill: var(--ui-danger-fill,#fef2f2);
}
.ds-status-tabs [data-status="paid"] {
  --filter-ink: var(--ui-success-ink,#059669);
  --filter-fill: var(--ui-success-fill,#ecfdf5);
}
.ds-status-count {
  display: inline-grid;
  place-items: center;
  min-width: 16px;
  min-height: 16px;
  padding-inline: 3px;
  border-radius: var(--ui-card-radius,16px);
  background: var(--filter-fill);
  color: var(--filter-ink);
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.ds-status-tabs [aria-checked="true"] {
  color: var(--brand-blue,#0032ff);
  font-weight: 600;
}
.ds-status-tabs [aria-checked="true"]::after {
  position: absolute;
  inset: auto 2px 0;
  height: 2px;
  border-radius: 1px;
  background: currentColor;
  content: "";
}
.orders-page .ds-status-tabs button:active {
  transform: none;
}
.ds-status-tabs button:focus-visible {
  outline-offset: -2px;
}

.ds-utility-card{font-family:"Source Han Sans SC", "Noto Sans CJK SC", "PingFang SC", "Microsoft YaHei", sans-serif;}.ds-utility-card{padding:16px;border-radius:20px;background:#fff;box-shadow:var(--ui-card-shadow);}.ds-grid{--utility-columns:4;--utility-divider:#f1f4f8;display:grid;grid-template-columns:repeat(var(--utility-columns), minmax(0, 1fr));grid-auto-rows:1fr;gap:0;margin-top:8px;border:1px solid var(--utility-divider);border-radius:12px;overflow:hidden;}.ds-grid[data-columns="3"]{--utility-columns:3;}.ds-grid > .ds-grid-item{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:0;min-height:60px;gap:3px;padding:5px 3px;border:0;border-radius:0;background:transparent;box-shadow:none;font-size:13px;font-weight:500;line-height:20px;color:#4f5f76;text-align:center;overflow-wrap:anywhere;}.ds-grid:not([data-columns="3"]) > .ds-grid-item:not(:nth-child(4n)),
.ds-grid[data-columns="3"] > .ds-grid-item:not(:nth-child(3n)){border-inline-end:1px solid var(--utility-divider);}.ds-grid:not([data-columns="3"]) > .ds-grid-item:nth-child(n + 5),
.ds-grid[data-columns="3"] > .ds-grid-item:nth-child(n + 4){border-block-start:1px solid var(--utility-divider);}.ds-grid > .ds-grid-item:focus-visible{position:relative;z-index:1;outline-offset:-3px;}.ds-grid > .ds-grid-item:active{transform:none;}.ds-grid > .ds-grid-item:not([aria-disabled="true"]):active{background:#f4f7ff;}.ds-grid .ds-grid-icon{--tool-icon-light:#e5ebf4;--tool-icon-accent:#6583bc;position:relative;display:grid;place-items:center;flex:none;width:26px;height:26px;color:#7488a3;}.ds-grid .ds-grid-icon svg{width:24px;height:24px;stroke:none;}.ds-grid > .ds-grid-item > span:not(.ds-grid-icon){width:100%;}.ds-grid-detail{display:block;flex:none;min-height:18px;font-size:12px;font-weight:400;line-height:18px;color:#59677a;}.ds-grid-label{display:flex;flex:none;align-items:center;justify-content:center;min-height:40px;line-height:20px;white-space:normal;overflow-wrap:anywhere;}.ds-utility-card>h2{margin:0;font-size:16px;font-weight:600;line-height:24px;color:var(--ui-heading,#203858);}.ds-grid-item{font-family:inherit;cursor:pointer;}.ds-grid-item:focus-visible{outline:3px solid var(--brand-blue,#0032ff);}.ds-grid-icon{--tool-icon-detail:color-mix(in srgb,var(--brand-blue,#0032ff) 57%,#8192bb)}.ds-grid-item:nth-child(even) .ds-grid-icon{--tool-icon-detail:color-mix(in srgb,var(--brand-purple,#7323fa) 50%,#8595bd)}.ds-grid-icon small{position:absolute;right:-4px;bottom:-2px;width:16px;height:12px;text-align:center;border-radius:3px;background:#f3ead6;color:#806329;font-size:9px;line-height:12px}

.feedback-toast {
  position: relative;
  z-index: 2;

  inset-inline: auto;

  display: flex;
  align-items: center;
  justify-content: center;
  width: max-content;
  max-width: calc(100% - 48px);
  min-height: var(--ui-touch-min,44px);
  margin: 0 auto;
  padding: 10px 14px;
  border-radius: var(--ui-toast-radius,12px);
  background: var(--ui-toast-fill,#26364a);
  color: white;
  font-size: var(--ui-toast-font,14px);
  line-height: 1.5;
  text-align: center;
  overflow-wrap: anywhere;
  pointer-events: none;
}
